const raw =
  $json.output ||
  $json.text ||
  $json.response ||
  $json.message ||
  JSON.stringify($json);

let content = typeof raw === "string" ? raw : JSON.stringify(raw);

const match = content.match(/\{[\s\S]*\}/);
if (match) {
  content = match[0];
}

let data;

try {
  data = JSON.parse(content);
} catch (error) {
  data = {
    success: false,
    needsMoreInfo: true,
    message: "Je n'ai pas réussi à traiter correctement votre demande. Pouvez-vous reformuler ?",
    raw
  };
}

return [{ json: data }];
